if.script:
try {
    Map sources = org.moqui.jexl.script.ReadStep.resolveSources(ec, org.moqui.jexl.script.ReadSpec.parse(readSpecJson))
    if (!sources.ok) ec.message.addError(sources.message as String)
} catch (org.moqui.jexl.script.ReadSpec.Invalid e) {
    ec.message.addError("Read spec: ${e.message}".toString())
}

def before = ec.entity.find('jexl.script.UserScript').condition('userScriptId', userScriptId).disableAuthz().useCache(false).one()
boolean changed = before != null && (before.scriptBody != scriptBody || (before.readSpecJson ?: null) != (readSpecJson ?: null) ||
        before.scriptProfile != checked.profile)
if (changed) {
    def others = ec.entity.find('jexl.script.UserScriptDeployment').condition('userScriptId', userScriptId)
            .condition('isActive', 'Y').condition('ownerUserId', org.moqui.entity.EntityCondition.NOT_EQUAL, ec.user.userId)
            .disableAuthz().useCache(false).list()
    if (others) {
        if (!ec.user.userId || !org.moqui.jexl.ScriptDeploymentRunner.maySchedule(ec, ec.user.userId)) {
            def owner = ec.entity.find('moqui.security.UserAccount').condition('userId', others[0].ownerUserId).disableAuthz().one()
            ec.message.addError("Not saved: this script runs on a schedule owned by ${owner?.username ?: others[0].ownerUserId}, and changing it needs permission to schedule scripts.".toString())
        } else {
            others.each { it.set('ownerUserId', ec.user.userId); it.update() }
        }
    }
}

org.moqui.jexl.script.ReadSpec spec = null
try {
    spec = org.moqui.jexl.script.ReadSpec.parse(readSpecJson)
} catch (org.moqui.jexl.script.ReadSpec.Invalid e) {
    ok = false; error = [kind: 'READ_ERROR', message: "Read spec: ${e.message}".toString()]; return
}
Map read = org.moqui.jexl.script.ReadStep.run(ec, spec, ec.user.userId, ec.user.userId, ec.user.nowTimestamp,
        ec.user.timeZone?.ID, org.moqui.jexl.ScriptProfiles.get(scriptProfile))
if (!read.ok) { ok = false; error = [kind: read.status, message: read.message]; return }
input = read.input
readCounts = read.readCounts

try {
    input = org.moqui.jexl.ScriptSupervisor.parseInputJson(inputJson, scriptProfile)
} catch (IllegalArgumentException e) {
    ec.message.addError(e.message)
}

actions.script:
Map out = org.moqui.jexl.script.ScriptDeliveries.email(ec, scriptDeployment, delivery?.parameters ?: [:], scriptResult, files)
if (out.error) { ec.message.addError(out.error as String); return }
outcome = out.outcome; message = out.message

Map out = org.moqui.jexl.script.ScriptDeliveries.notification(ec, scriptDeployment, delivery?.parameters ?: [:], scriptResult, files)
if (out.error) { ec.message.addError(out.error as String); return }
outcome = out.outcome; message = out.message

try {
    org.moqui.impl.service.ScheduledJobRunner.getCron(cronExpression.trim())
} catch (Exception e) {
    ec.message.addError("'${cronExpression}' is not a Quartz cron expression: ${e.message}")
}
if (timeZone) {
    try { java.time.ZoneId.of(timeZone) } catch (Exception e) { ec.message.addError("'${timeZone}' is not a time zone id.") }
}
